-- Translate saved built-in speech without changing custom prompts, keys, files or volume.
UPDATE audio_cues SET config = json_set(config, '$.text', 'Small and cozy. And please put the toilet indoors.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Klein, gemütlich. Und das Klo bitte drinnen.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'A bed. A table. And absolutely no more work.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Ein Bett. Ein Tisch. Bloß keine Arbeit mehr.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'There are six of us. We like to sit down.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Wir sind sechs. Wir sitzen gern.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Inspection passed! With reservations. But with style.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Abgenommen! Unter Vorbehalt. Aber mit Stil.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Built with good intentions! The inspector is looking the other way today.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Gut gemeint ist auch gebaut. Das Bauamt drückt heute ein Auge zu.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Roof-raising in five minutes! Twelve bricks, two posts, two roof panels. All hands on trowels!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Richtfest in fünf Minuten! Zwölf Ziegel, zwei Stützen, zwei Dachplatten. Alle Hände an die Kelle!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'The roof is up! Great work, team!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Richtfest! Das Dach steht. Gut gemacht, Team!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Time is up. We can still keep building!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Die Zeit ist um. Weiterbauen können wir trotzdem!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'The mixer is jammed. Anyone nearby? Give it a nudge!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Der Mischer streikt. Wer ist in der Nähe? Gib ihm einen Stups!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'The mixer is running again. A nudge counts as a repair!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Der Mischer läuft wieder. Ein Stups ist auch eine Reparatur!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'It was like that when I got here!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Das war schon so!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Fits. Wobbles. Plenty of ventilation.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Passt. Wackelt. Hat Luft.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'That is load-bearing decor.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Das ist tragende Deko.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'One more turn and it snaps.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Nach fest kommt ab.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'I saw this on the internet.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Ich hab das im Internet gesehen.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'That angle is artistic license.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Der Winkel ist künstlerische Freiheit.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Measure twice. Get it wrong anyway.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Wer misst, misst Mist.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'It is still drying.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Das trocknet noch.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'That screw was a spare.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Die Schraube war übrig.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'The boss wanted it that way.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Der Chef wollte das so.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Just five more minutes!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Nur noch fünf Minuten!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'It will hold until the inspection.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Das hält bis zur Abnahme.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'This is not a bodge. It is precision work with generous tolerances!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Das ist kein Pfusch. Das ist Maßarbeit mit Toleranz!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Who held the spirit level at an angle?') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Wer hat die Wasserwaage schief gehalten?';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Boss, it was like that when I got here!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Chef, das war vorher schon so!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'It will hold. I gave it a good look.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Hält. Ich habe dran geguckt.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Measured twice. Still missed!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Zweimal gemessen, trotzdem daneben!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Bring mortar! My brick is getting cold!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Bring Mörtel! Mein Stein friert!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'This is no wall. It is a monument!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Das wird keine Wand. Das wird ein Denkmal!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'I am the load-bearing personality around here.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Ich bin die tragende Persönlichkeit hier.';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Nobody clocks off until the roof is on!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Feierabend ist erst, wenn das Dach drauf ist!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'Can somebody hold gravity for a second?') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Kann mal jemand kurz die Schwerkraft halten?';
UPDATE audio_cues SET config = json_set(config, '$.text', 'That gap is for ventilation!') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Die Lücke ist für die Lüftung!';
UPDATE audio_cues SET config = json_set(config, '$.text', 'We are building memories. And hopefully a house.') WHERE cue LIKE 'speech.%' AND json_extract(config, '$.text') = 'Wir bauen Erinnerungen. Und hoffentlich ein Haus.';
-- Remove old transient status copy; preserve buildings, inventories, scores and sessions.
UPDATE rooms SET world = json_set(world, '$.events', json('[]')), version = version + 1;
UPDATE fp_rooms SET world = json_set(world, '$.notice', NULL), version = version + 1;
UPDATE audio_cues SET error = '';
